// swift-tools-version: 6.0
// MixAI Key & BPM Rust engine for Apple platforms (WP18-05, D69): crates/mixai-listen-ffi over UniFFI.
// KeyBpmFFI.xcframework and Sources/KeyBpmFFI/mixai_listen_ffi.swift are GENERATED by
// apps/ios/scripts/build-keybpm-xcframework.sh and gitignored; only this manifest is committed. Without the
// xcframework the package declares no binary target, so the shared XcodeGen project still resolves for other apps.
import Foundation
import PackageDescription

let hasBinary = FileManager.default.fileExists(atPath: Context.packageDirectory + "/KeyBpmFFI.xcframework")

let package = Package(
    name: "KeyBpmFFI",
    platforms: [
        .iOS("26.0"),
        .watchOS("11.0"),
    ],
    products: [
        .library(name: "KeyBpmFFI", targets: ["KeyBpmFFI"]),
    ],
    targets: [
        .target(
            name: "KeyBpmFFI",
            dependencies: hasBinary ? ["mixai_listen_ffiFFI"] : [],
            path: "Sources/KeyBpmFFI",
            linkerSettings: [
                .linkedLibrary("c++"),
                .linkedLibrary("resolv"),
                .linkedFramework("Foundation"),
                .linkedFramework("CoreFoundation"),
                .linkedFramework("Security"),
            ]
        ),
    ] + (hasBinary ? [.binaryTarget(name: "mixai_listen_ffiFFI", path: "KeyBpmFFI.xcframework")] : []),
    // UniFFI-generated Swift keeps process-wide globals; compile it in Swift 5 mode.
    swiftLanguageModes: [.v5]
)
